fn putmask(a: Vec<f32>, mask: Vec<bool>, values: Vec<f32>) -> Vec<f32> {
    // Precondition checks (optional, based on problem assumptions)
    assert_eq!(a.len(), mask.len(), "Input and mask must have the same length");
    assert!(
        !values.is_empty(),
        "Replacement values array must have at least one element"
    );

    let val_len = values.len();
    let mut result = Vec::with_capacity(a.len());

    for (i, x) in a.into_iter().enumerate() {
        if mask[i] {
            // Use `i % val_len` to cycle through `values`
            result.push(values[i % val_len]);
        } else {
            // Keep the original element
            result.push(x);
        }
    }

    result
}

