        let a = vec![1.0, 2.0, 3.0, 4.0];
        let mask = vec![false, true, false, true];
        let values = vec![10.0, 20.0];
        // mask[1] => values[1 % 2] = 20.0
        // mask[3] => values[3 % 2] = 20.0
        let expected = vec![1.0, 20.0, 3.0, 20.0];
        assert_eq!(putmask(a, mask, values), expected);
